    {'cat': 'remark', 'text': 'Ce soir, il me faut de la chance. Ou une héritière. Ou les deux.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_remark_30', 'whispered': False, 'nonverbal': False, 'gun': False},
