    {'cat': 'remark', 'text': 'Trois coupes sur le piano. Deux rouges à lèvres différents. Une histoire.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_23', 'whispered': False, 'nonverbal': False, 'gun': False},
