    {'cat': 'remark', 'text': "Le majordome m'a appelée « mademoiselle Odette ». Personne m'appelle comme ça, à Pigalle.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_25', 'whispered': False, 'nonverbal': False, 'gun': False},
